  // Companies in the final results.
// Code-rule validation of raw companies. Pure and deterministic: the same
// input always gives the same output, and no rule ever throws.

import type {
  RawCompany,
  Validation,
  ValidationIssue,
  ValidationStatus,
} from "../types";
import { normalizeDomain, normalizeLinkedInUrl } from "./normalize";

// Hosts that are messaging, link-shortener or social pages, not real sites.
export const JUNK_HOSTS: readonly string[] = [
  "wa.link",
  "wa.me",
  "bit.ly",
  "linktr.ee",
  "facebook.com",
  "instagram.com",
  "t.me",
];

// Above this implied revenue per employee (USD) the data is not believable.
export const MAX_REVENUE_PER_EMPLOYEE_USD = 500000;

interface Range {
  readonly min: number;
  readonly max: number; // Infinity for open-ended ranges like "10,001+"
}

function toNumber(text: string): number | undefined {
  const n = Number(text.replace(/,/g, ""));
  return Number.isFinite(n) ? n : undefined;
}

// "51-200" -> {51, 200}; "10,001+" -> {10001, Infinity}; else undefined.
export function parseEmployeeRange(input: unknown): Range | undefined {
  if (typeof input !== "string") return undefined;
  const s = input.trim();
  const span = /^(\d[\d,]*)\s*[-–]\s*(\d[\d,]*)$/.exec(s);
  if (span) {
    const min = toNumber(span[1]);
    const max = toNumber(span[2]);
    if (min === undefined || max === undefined || max < min) return undefined;
    return { min, max };
  }
  const open = /^(\d[\d,]*)\s*\+$/.exec(s);
  if (open) {
    const min = toNumber(open[1]);
    return min === undefined ? undefined : { min, max: Infinity };
  }
  return undefined;
}

const SUFFIX: Readonly<Record<string, number>> = {
  "": 1,
  k: 1e3,
  m: 1e6,
  b: 1e9,
};

// Lower bound in USD of a range like "$10M-$50M", "$500K-$1M" or "$10M+".
// Undefined for anything else (e.g. "<$1M", "unknown").
export function parseRevenueLowerBound(input: unknown): number | undefined {
  if (typeof input !== "string") return undefined;
  const m = /^\$?\s*(\d[\d,]*(?:\.\d+)?)\s*([kmb]?)\s*(?:[-–]|to\b|\+|$)/i.exec(
    input.trim(),
  );
  if (!m) return undefined;
  const base = toNumber(m[1]);
  if (base === undefined) return undefined;
  return base * (SUFFIX[m[2].toLowerCase()] ?? 1);
}

function isEmpty(value: unknown): boolean {
  return typeof value !== "string" || value.trim() === "";
}

function isJunkHost(host: string): boolean {
  return JUNK_HOSTS.some((j) => host === j || host.endsWith(`.${j}`));
}

// Key used to group duplicates: domain first, LinkedIn URL when no domain.
function duplicateKey(raw: RawCompany): string | undefined {
  const domain = normalizeDomain(raw.primary_domain);
  if (domain) return `domain:${domain}`;
  const linkedin = normalizeLinkedInUrl(raw.professional_network_url);
  if (linkedin) return `linkedin:${linkedin}`;
  return undefined;
}

function sizeIssues(raw: RawCompany): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const headcount = raw.latest_headcount;
  if (
    typeof headcount !== "number" ||
    !Number.isFinite(headcount) ||
    headcount <= 0
  ) {
    return issues;
  }

  const range = parseEmployeeRange(raw.employee_count_range);
  if (range && (headcount < range.min || headcount > range.max)) {
    issues.push({
      code: "size_headcount_mismatch",
      field: "latest_headcount",
      reason: `Headcount ${headcount} is outside the listed size range "${raw.employee_count_range}".`,
    });
  }

  const revenueMin = parseRevenueLowerBound(raw.revenue_range);
  if (
    revenueMin !== undefined &&
    revenueMin / headcount > MAX_REVENUE_PER_EMPLOYEE_USD
  ) {
    issues.push({
      code: "size_headcount_mismatch",
      field: "revenue_range",
      reason: `Revenue "${raw.revenue_range}" with ${headcount} employees implies more than $${MAX_REVENUE_PER_EMPLOYEE_USD.toLocaleString("en-US")} per employee, which is implausible.`,
    });
  }
  return issues;
}

export function validateCompanies(
  raws: readonly RawCompany[],
): readonly Validation[] {
  const firstSeen = new Map<string, number>(); // key -> crustdata_company_id

  return raws.map((raw): Validation => {
    const issues: ValidationIssue[] = [];

    const noName = isEmpty(raw.name);
    const domain = normalizeDomain(raw.primary_domain ?? "");
    const linkedin = normalizeLinkedInUrl(raw.professional_network_url ?? "");

    if (noName) {
      issues.push({
        code: "missing_name",
        field: "name",
        reason: "The company has no name.",
      });
    }
    if (!domain) {
      issues.push({
        code: "missing_domain",
        field: "primary_domain",
        reason: "The company has no primary domain.",
      });
    }

    const host = normalizeDomain(raw.website ?? "");
    if (host && isJunkHost(host)) {
      issues.push({
        code: "junk_website",
        field: "website",
        reason: `The website points to ${host}, a messaging, link-shortener or social page rather than a company site.`,
      });
    }

    if (!linkedin) {
      issues.push({
        code: "missing_linkedin",
        field: "professional_network_url",
        reason: "The company has no LinkedIn page.",
      });
    }

    let isLaterDuplicate = false;
    const key = duplicateKey(raw);
    if (key !== undefined) {
      const keptId = firstSeen.get(key);
      if (keptId === undefined) {
        firstSeen.set(key, raw.crustdata_company_id);
      } else {
        isLaterDuplicate = true;
        const viaDomain = key.startsWith("domain:");
        issues.push({
          code: "duplicate_domain",
          field: viaDomain ? "primary_domain" : "professional_network_url",
          reason: viaDomain
            ? `Another company (id ${keptId}) already uses the domain ${domain}.`
            : `Another company (id ${keptId}) already uses the LinkedIn page ${linkedin}.`,
          related_company_id: keptId,
        });
      }
    }

    issues.push(...sizeIssues(raw));

    let status: ValidationStatus;
    if ((noName && !domain && !linkedin) || isLaterDuplicate) {
      status = "rejected";
    } else if (issues.length > 0) {
      status = "flagged";
    } else {
      status = "valid";
    }
    return { status, issues };
  });
}
// Deterministic guardrails on model output, run by the improved pipeline.
// validateAssessment() checks scores and fact references; checkClaims()
// checks that outreach rests only on citeable facts. Neither calls a model,
// and neither changes a fact's status.

import { type AnyFact, type Assessment, CITEABLE_FACT_STATUSES, type OutreachDraft } from "../types";
import type { CheckFinding, CheckResult } from "./types";

// Shared rule (see OutreachDraft in src/core/types.ts): a fact may be cited
// only when its status is citeable and it did not come from the model.
export function isCiteableFact(fact: AnyFact): boolean {
  return CITEABLE_FACT_STATUSES.includes(fact.status) && fact.source.provider !== "model";
}

function normaliseCriterion(name: string): string {
  return name.trim().toLowerCase();
}

function inScoreRange(n: number): boolean {
  return Number.isFinite(n) && n >= 0 && n <= 100;
}

function result(findings: CheckFinding[]): CheckResult {
  return { ok: findings.every((f) => f.severity !== "error"), findings };
}

// Checks one company's assessment against the criteria it was asked to score
// and the facts that exist for that company.
// - fit_score and every criterion score must be in 0..100.
// - Each expected criterion must be scored exactly once (case-insensitive),
//   and nothing else may be scored.
// - Every referenced fact id must exist for this company. Referencing an
//   uncertain fact is allowed in a score (it can explain a low score) but is
//   recorded as a warning.
export function validateAssessment(
  assessment: Assessment,
  facts: readonly AnyFact[],
  expected_criteria: readonly string[],
): CheckResult {
  const findings: CheckFinding[] = [];
  const byId = new Map(facts.map((f) => [f.id, f]));

  if (!inScoreRange(assessment.fit_score)) {
    findings.push({
      code: "fit_score_out_of_range",
      severity: "error",
      message: `fit_score ${assessment.fit_score} is outside 0-100.`,
    });
  }

  const expected = new Map(expected_criteria.map((c) => [normaliseCriterion(c), c]));
  const seen = new Set<string>();
  for (const score of assessment.criterion_scores) {
    const key = normaliseCriterion(score.criterion);
    if (!expected.has(key)) {
      findings.push({
        code: "unexpected_criterion",
        severity: "error",
        message: `"${score.criterion}" is not one of the requested criteria.`,
        criterion: score.criterion,
      });
    } else if (seen.has(key)) {
      findings.push({
        code: "duplicate_criterion",
        severity: "error",
        message: `"${score.criterion}" is scored more than once.`,
        criterion: score.criterion,
      });
    }
    seen.add(key);

    if (!inScoreRange(score.score)) {
      findings.push({
        code: "criterion_score_out_of_range",
        severity: "error",
        message: `Score ${score.score} for "${score.criterion}" is outside 0-100.`,
        criterion: score.criterion,
      });
    }

    for (const id of score.fact_ids) {
      const fact = byId.get(id);
      if (!fact) {
        findings.push({
          code: "unknown_fact_reference",
          severity: "error",
          message: `"${score.criterion}" references ${id}, which is not a fact for this company.`,
          fact_id: id,
          criterion: score.criterion,
        });
      } else if (fact.status === "uncertain") {
        findings.push({
          code: "uncertain_fact_reference",
          severity: "warning",
          message: `"${score.criterion}" references ${id}, which is uncertain.`,
          fact_id: id,
          criterion: score.criterion,
        });
      }
    }
  }

  for (const [key, original] of expected) {
    if (!seen.has(key)) {
      findings.push({
        code: "missing_criterion",
        severity: "error",
        message: `"${original}" was not scored.`,
        criterion: original,
      });
    }
  }

  return result(findings);
}

// Numbers as written in text: "1,200" -> "1200", "2.5" stays, trailing
// punctuation dropped.
function numberTokens(text: string): string[] {
  return (text.match(/\d[\d,]*(?:\.\d+)?/g) ?? []).map((t) => t.replace(/,/g, ""));
}

// Checks an outreach draft against the company's facts.
// - It must cite at least one fact.
// - Every cited id must exist for this company, have a citeable status, and
//   not come from the model.
// - Every number in the body must appear in a citeable fact it cites, so an
//   unknown figure cannot be stated as established.
export function checkClaims(outreach: OutreachDraft, facts: readonly AnyFact[]): CheckResult {
  const findings: CheckFinding[] = [];
  const byId = new Map(facts.map((f) => [f.id, f]));

  if (outreach.cited_fact_ids.length === 0) {
    findings.push({
      code: "no_citations",
      severity: "error",
      message: "The outreach cites no facts.",
    });
  }

  const supporting: AnyFact[] = [];
  const seen = new Set<string>();
  for (const id of outreach.cited_fact_ids) {
    if (seen.has(id)) {
      findings.push({
        code: "duplicate_citation",
        severity: "warning",
        message: `${id} is cited more than once.`,
        fact_id: id,
      });
      continue;
    }
    seen.add(id);
    const fact = byId.get(id);
    if (!fact) {
      findings.push({
        code: "unknown_citation",
        severity: "error",
        message: `${id} is not a fact for this company.`,
        fact_id: id,
      });
    } else if (fact.source.provider === "model") {
      findings.push({
        code: "model_fact_citation",
        severity: "error",
        message: `${id} came from the model and cannot be cited.`,
        fact_id: id,
      });
    } else if (!isCiteableFact(fact)) {
      findings.push({
        code: "non_citeable_citation",
        severity: "error",
        message: `${id} has status "${fact.status}", which cannot be cited.`,
        fact_id: id,
      });
    } else {
      supporting.push(fact);
    }
  }

  const supportedNumbers = new Set(
    supporting.flatMap((f) => [...numberTokens(f.claim), ...numberTokens(String(f.value))]),
  );
  for (const n of new Set(numberTokens(outreach.body))) {
    if (!supportedNumbers.has(n)) {
      findings.push({
        code: "unsupported_number",
        severity: "error",
        message: `The outreach states "${n}", which no cited citeable fact supports.`,
      });
    }
  }

  return result(findings);
}
